// Recebe o evento do Chatwoot (bot de agente) e converte no formato único.
// Só responde mensagens da cliente em conversas com status "pending" (com o bot).
// Conversas "open" estão com a equipe: a IA fica quieta e o Chatwoot avisa a atendente.
const b = $json.body ?? $json;
const tipo = b.message_type;
const conversa = b.conversation ?? {};
if (b.event !== 'message_created') return [];
if (!(tipo === 'incoming' || tipo === 0) || b.private) return [];
if (conversa.status && conversa.status !== 'pending') return [];

const remetente = b.sender ?? conversa.meta?.sender ?? {};
let texto = (b.content || '').trim();
if (!texto && (b.attachments || []).length) {
  const t = b.attachments[0].file_type;
  texto = t === 'image' ? '[A cliente enviou uma imagem]' : t === 'audio' ? '[A cliente enviou um áudio]' : '[A cliente enviou um arquivo]';
}
if (!texto) return [];

return [{ json: {
  canal: 'whatsapp',
  id_conversa: 'cw:' + conversa.id,
  telefone: (remetente.phone_number || '').replace(/\D/g, '') || null,
  email: remetente.email || null,
  nome: remetente.name || null,
  texto,
  recebida_em: b.created_at ? new Date(b.created_at).toISOString() : new Date().toISOString(),
  chatwoot: { account_id: b.account?.id, conversation_id: conversa.id, inbox_id: b.inbox?.id },
}}];

// Converte o envio do formulário Fale Conosco no mesmo formato do WhatsApp.
const j = $input.first().json;
const pedido = (j['Número do pedido (opcional)'] || '').trim();
const texto = [
  j['Assunto'] ? `Assunto: ${j['Assunto']}` : '',
  pedido ? `Pedido: ${pedido}` : '',
  (j['Mensagem'] || '').trim(),
].filter(Boolean).join('\n');
const email = (j['E-mail'] || '').trim().toLowerCase();
return [{ json: {
  canal: 'formulario',
  id_conversa: 'form:' + email + ':' + Date.now(),
  telefone: (j['WhatsApp (opcional)'] || '').replace(/\D/g, '') || null,
  email,
  nome: (j['Nome'] || '').trim() || null,
  texto,
  recebida_em: j.submittedAt || new Date().toISOString(),
}}];

// ================= CONFIGURAÇÕES =================
// Valores vêm das variáveis MALUVIA_* do infra/.env; o segundo valor é o padrão.
const env = (nome, padrao) => { try { return $env[nome] || padrao; } catch (e) { return padrao; } };
const CONFIG = {
  modelo_ia: env('MALUVIA_MODELO_IA', 'claude-haiku-5-5'),
  chatwoot_url: env('MALUVIA_CHATWOOT_URL', 'http://rails:3000'),   // endereço do Chatwoot visto pelo n8n
  email_remetente: env('MALUVIA_EMAIL_REMETENTE', 'atendimento@exemplo.com'),
  email_equipe: env('MALUVIA_EMAIL_EQUIPE', 'equipe@exemplo.com'),
  max_historico: 10,          // mensagens guardadas por conversa
  limite_tentativas: 2,       // respostas sem resolver antes de transferir
};

// ============ PEDIDOS FICTÍCIOS (depois virão do ERP/site) ============
const PEDIDOS = {
  'MLV-1001': { cliente: 'Ana Souza', status: 'Pagamento confirmado, aguardando postagem', itens: 'Vestido midi de linho (M), Colar ponto de luz dourado', valor: 'R$ 289,90', rastreio: null, previsao: 'Postagem em até 2 dias úteis' },
  'MLV-1002': { cliente: 'Beatriz Lima', status: 'Enviado pelos Correios (PAC)', itens: 'Calça pantalona (G), Blusa de tricô (G)', valor: 'R$ 349,80', rastreio: 'QB123456789BR', previsao: 'Entrega prevista em 3 dias úteis' },
  'MLV-1003': { cliente: 'Carla Mendes', status: 'Entregue em 15/10/2026', itens: 'Saia plissada (P), Brinco argola dourado', valor: 'R$ 159,90', rastreio: 'QB987654321BR', previsao: null },
  'MLV-1004': { cliente: 'Daniela Rocha', status: 'Aguardando pagamento (boleto)', itens: 'Macacão alfaiataria (M)', valor: 'R$ 399,90', rastreio: null, previsao: 'Boleto vence em 2 dias' },
  'MLV-1005': { cliente: 'Elisa Prado', status: 'Enviado, entrega atrasada (previsão era 18/10/2026)', itens: 'Jaqueta jeans (GG)', valor: 'R$ 279,90', rastreio: 'QB555666777BR', previsao: 'Atrasada' },
};

const msg = { ...$json };
const base = msg.base_conhecimento || '';
delete msg.base_conhecimento;

// Memória das conversas (só é salva com o fluxo ATIVO, não em testes manuais)
const dados = $getWorkflowStaticData('global');
dados.conversas = dados.conversas || {};
const conv = dados.conversas[msg.id_conversa] || { historico: [], com_atendente: false, tentativas_sem_resolver: 0, criada_em: msg.recebida_em };
dados.conversas[msg.id_conversa] = conv;

// Quem decide se a IA responde é o status da conversa no Chatwoot.
// Se a conversa voltou para o bot depois de passar pela equipe, recomeça o histórico.
if (conv.com_atendente) { conv.com_atendente = false; conv.historico = []; conv.tentativas_sem_resolver = 0; }

conv.historico.push({ role: 'user', content: msg.texto || '(mensagem vazia)' });
conv.historico = conv.historico.slice(-CONFIG.max_historico);

// Pedido citado na mensagem (ou o último citado na conversa)
const achado = (msg.texto || '').match(/MLV[\s-]?(\d{4})/i);
const numero = achado ? `MLV-${achado[1]}` : (conv.ultimo_pedido || null);
let pedido = null;
if (numero) {
  pedido = PEDIDOS[numero] ? { numero, ...PEDIDOS[numero] } : { numero, nao_encontrado: true };
  if (PEDIDOS[numero]) conv.ultimo_pedido = numero;
}
const pedidoTexto = !pedido
  ? 'Nenhum número de pedido informado.'
  : pedido.nao_encontrado
    ? `A cliente citou o pedido ${pedido.numero}, mas ele não foi encontrado. Peça para conferir o número; se insistir, transfira.`
    : Object.entries(pedido).filter(([, v]) => v).map(([k, v]) => `${k}: ${v}`).join('\n');

// Palavras que levam direto para a equipe, mesmo que a IA não perceba
const GATILHOS = /(atendente|humano|pessoa de verdade|falar com algu[eé]m|reclama|procon|reclame aqui|defeito|estorno|reembolso|devolver o dinheiro|cancelar|alergia|al[eé]rgic|irrita[çc][aã]o|descasc|escureceu|golpe|absurdo|p[eé]ssimo|horr[ií]vel)/i;
const gatilho = GATILHOS.test(msg.texto || '');

const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'long', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const ehWhats = msg.canal === 'whatsapp';

const system = `Você é a Malu, a assistente virtual da Maluvia, uma loja virtual de moda feminina que vende roupas e semijoias. Você atende clientes pelo ${ehWhats ? 'WhatsApp' : 'formulário Fale Conosco do site (sua resposta será enviada por e-mail)'}.

REGRAS
- Responda somente com base na BASE DE CONHECIMENTO e nos DADOS DO PEDIDO abaixo. Se a resposta não estiver ali, não invente: diga que vai encaminhar para a equipe e marque "transferir": true.
- Nunca prometa reembolso, desconto, cupom, brinde ou prazo que não esteja na base.
- Reclamação, produto com defeito, cancelamento, pedido de reembolso ou estorno, entrega atrasada ou cliente irritada: acolha em uma frase, diga que a equipe vai assumir e marque "transferir": true.
- Se a cliente pedir para falar com uma pessoa, transfira.
- Dúvida sobre um pedido sem o número: peça o número no formato MLV-0000.
- Nunca peça senha, número de cartão ou CPF completo.
- ${conv.historico.length === 1 ? 'Esta é a primeira mensagem da conversa: apresente-se como Malu, a assistente virtual da Maluvia.' : 'A conversa já começou: não se apresente de novo.'}
- Tom: simpático e direto, em português do Brasil. ${ehWhats ? 'No WhatsApp, seja breve: até 3 frases curtas ou uma lista pequena. Para negrito use *uma estrela*, nunca **duas**. No máximo um emoji.' : 'No e-mail, comece com "Olá, ' + (msg.nome || 'tudo bem') + '!" e termine com "Equipe Maluvia".'}

BASE DE CONHECIMENTO
${base}

DADOS DO PEDIDO
${pedidoTexto}

AGORA: ${agora}

FORMATO DA RESPOSTA
Responda APENAS com um objeto JSON válido, sem nada antes ou depois:
{"categoria": "produto|tamanho|pagamento|envio_frete|status_pedido|troca|devolucao|defeito|reclamacao|outro", "resposta": "texto para a cliente", "transferir": true ou false, "motivo_transferencia": "texto curto, ou vazio", "resolvido": true ou false}`;

// A API exige mensagens alternadas começando pela cliente
const mensagens = [];
for (const h of conv.historico) {
  const ultima = mensagens[mensagens.length - 1];
  if (ultima && ultima.role === h.role) ultima.content += '\n' + h.content;
  else mensagens.push({ role: h.role, content: h.content });
}
while (mensagens.length && mensagens[0].role !== 'user') mensagens.shift();

return [{ json: {
  ...msg,
  config: CONFIG,
  pedido,
  gatilho_transferencia: gatilho,
  requisicao_ia: { model: CONFIG.modelo_ia, max_tokens: 700, system, messages: mensagens },
}}];

// Lê a resposta da IA, aplica as regras de transferência e registra o atendimento.
const ctx = $('Montar contexto').first().json;
const CONFIG = ctx.config;
const bruto = $json.content?.[0]?.text ?? '';

let r;
try {
  r = JSON.parse(bruto.slice(bruto.indexOf('{'), bruto.lastIndexOf('}') + 1));
  if (!r.resposta) throw new Error('sem resposta');
} catch (e) {
  r = { categoria: 'outro', resposta: 'Desculpe, tive um problema para responder agora. Vou passar sua mensagem para a nossa equipe, que retorna em breve.', transferir: true, motivo_transferencia: 'Falha ao ler a resposta da IA', resolvido: false };
}

const dados = $getWorkflowStaticData('global');
dados.conversas = dados.conversas || {};
const conv = dados.conversas[ctx.id_conversa] || { historico: [], tentativas_sem_resolver: 0 };
dados.conversas[ctx.id_conversa] = conv;

let transferir = r.transferir === true;
let motivo = r.motivo_transferencia || '';
let resposta = String(r.resposta).trim();

if (r.resolvido === true) conv.tentativas_sem_resolver = 0;
else if (!transferir) conv.tentativas_sem_resolver = (conv.tentativas_sem_resolver || 0) + 1;

if (!transferir && ctx.gatilho_transferencia) { transferir = true; motivo = 'Palavra-chave de transferência na mensagem'; }
if (!transferir && conv.tentativas_sem_resolver >= CONFIG.limite_tentativas) { transferir = true; motivo = `${CONFIG.limite_tentativas} respostas sem resolver`; }
if (transferir && r.transferir !== true) {
  resposta += ctx.canal === 'whatsapp'
    ? '\n\nVou passar sua conversa para a nossa equipe, que continua o atendimento por aqui. 😊'
    : '\n\nEncaminhei sua mensagem para a nossa equipe, que vai responder em breve.';
}

conv.historico.push({ role: 'assistant', content: resposta });
conv.historico = conv.historico.slice(-CONFIG.max_historico);
if (transferir) { conv.com_atendente = true; conv.transferida_em = new Date().toISOString(); conv.tentativas_sem_resolver = 0; }

// Registro para acompanhar resultados (últimos 1000 atendimentos)
dados.registro = dados.registro || [];
dados.registro.push({
  quando: new Date().toISOString(), canal: ctx.canal, conversa: ctx.id_conversa, nome: ctx.nome,
  categoria: r.categoria || 'outro', transferido: transferir, motivo: motivo || null,
  pedido: ctx.pedido?.numero || null, mensagem: ctx.texto, resposta,
});
dados.registro = dados.registro.slice(-1000);

const contato = ctx.telefone ? '+' + ctx.telefone : ctx.email;
const aviso = transferir
  ? `🔔 Atendimento transferido pela IA\nCliente: ${ctx.nome || 'sem nome'} (${contato})\nCanal: ${ctx.canal}\nAssunto: ${r.categoria || 'outro'}\nMotivo: ${motivo || 'pedido da IA'}\nPedido: ${ctx.pedido?.numero || '-'}\nMensagem: "${ctx.texto}"`
  : null;

return [{ json: {
  canal: ctx.canal, telefone: ctx.telefone, email: ctx.email, nome: ctx.nome,
  categoria: r.categoria || 'outro', resposta, transferir, motivo, aviso_atendente: aviso,
  config: CONFIG, chatwoot: ctx.chatwoot || null,
}}];

// Resumo dos atendimentos. Acesse a URL do webhook com ?chave=MALUVIA_CHAVE_RELATORIO
let CHAVE = '';
try { CHAVE = $env.MALUVIA_CHAVE_RELATORIO || ''; } catch (e) {}
if (!CHAVE) return [{ json: { erro: 'Defina MALUVIA_CHAVE_RELATORIO no infra/.env' } }];
if (($json.query?.chave || '') !== CHAVE) return [{ json: { erro: 'Chave inválida' } }];

const reg = $getWorkflowStaticData('global').registro || [];
const respondidas = reg.filter(r => r.categoria !== 'com_atendente');
const resolvidasIA = respondidas.filter(r => !r.transferido).length;
const porCategoria = {};
for (const r of respondidas) porCategoria[r.categoria] = (porCategoria[r.categoria] || 0) + 1;
const porMotivo = {};
for (const r of respondidas.filter(r => r.transferido)) porMotivo[r.motivo || 'pedido da IA'] = (porMotivo[r.motivo || 'pedido da IA'] || 0) + 1;

return [{ json: {
  total_mensagens: reg.length,
  respondidas_pela_ia: respondidas.length,
  resolvidas_sem_equipe: resolvidasIA,
  taxa_resolucao_ia: respondidas.length ? Math.round(100 * resolvidasIA / respondidas.length) + '%' : '-',
  por_categoria: porCategoria,
  motivos_de_transferencia: porMotivo,
  ultimas_20: reg.slice(-20).reverse(),
} }];
